<?php
declare(strict_types=1);
namespace Flexgrid\Modules\AdminBanking\Infrastructure\Persistence;
use Flexgrid\Modules\AdminBanking\Contract\BankAccountRepositoryInterface;use Flexgrid\Modules\AdminBanking\Domain\Model\BankAccount;use Flexgrid\Modules\AdminCore\ValueObject\Currency;use Flexgrid\Modules\AdminCore\ValueObject\TenantId;
final class PdoBankAccountRepository implements BankAccountRepositoryInterface{private$connection;public function __construct(\PDO$connection){$this->connection=$connection;}public function insert(BankAccount$account,int$createdAt):void{$this->assertTransaction();$statement=$this->connection->prepare('INSERT INTO `admin_bank_account` (`tenant_id`,`public_id`,`name`,`account_reference`,`iban`,`currency`,`is_active`,`created_at`,`updated_at`) VALUES (:tenant,:public,:name,:reference,:iban,:currency,:active,:created,:updated)');$statement->execute([':tenant'=>$account->getTenantId()->toString(),':public'=>$account->getPublicId(),':name'=>$account->getName(),':reference'=>$account->getAccountReference(),':iban'=>$account->getIban()===''?null:$account->getIban(),':currency'=>$account->getCurrency()->getCode(),':active'=>$account->isActive()?1:0,':created'=>$createdAt,':updated'=>$createdAt]);}public function findByPublicId(TenantId$tenant,string$publicId):?BankAccount{return$this->find('`tenant_id`=:tenant AND `public_id`=:value',$tenant,trim($publicId));}public function findByAccountReference(TenantId$tenant,string$reference):?BankAccount{return$this->find('`tenant_id`=:tenant AND `account_reference`=:value',$tenant,strtoupper(preg_replace('/\s+/','',trim($reference))));}public function findAll(TenantId$tenant,bool$includeInactive=false):array{$sql='SELECT * FROM `admin_bank_account` WHERE `tenant_id`=:tenant'.($includeInactive?'':' AND `is_active`=1').' ORDER BY `name`,`account_reference`';$statement=$this->connection->prepare($sql);$statement->execute([':tenant'=>$tenant->toString()]);$items=[];foreach($statement->fetchAll(\PDO::FETCH_ASSOC)as$row){$items[]=$this->hydrate($row);}return$items;}private function find(string$where,TenantId$tenant,string$value):?BankAccount{if($value===''){throw new \InvalidArgumentException('Bankrekeningzoekwaarde is verplicht.');}$statement=$this->connection->prepare('SELECT * FROM `admin_bank_account` WHERE '.$where.' LIMIT 1');$statement->execute([':tenant'=>$tenant->toString(),':value'=>$value]);$row=$statement->fetch(\PDO::FETCH_ASSOC);return is_array($row)?$this->hydrate($row):null;}private function hydrate(array$row):BankAccount{return new BankAccount((string)$row['public_id'],new TenantId((string)$row['tenant_id']),(string)$row['name'],(string)$row['account_reference'],new Currency((string)$row['currency']),(string)($row['iban']??''),(bool)$row['is_active']);}private function assertTransaction():void{if(!$this->connection->inTransaction()){throw new \LogicException('Bankrekeningopslag vereist een actieve transactie.');}}}
